        LocalDateTime now = LocalDateTime.now();

        User admin = newUser("admin", "admin123", "管理员", UserRole.ADMIN, now);
        User demo = newUser("demo", "demo123", "演示用户", UserRole.USER, now);

        int dramaNo = 0;
        for (SeedDrama seed : SEED_DRAMAS) {
